// Üretilen dosya: tool/ozgun/uret.py. Matematik · Trigonometri (zor).
const ozMathematics10Zor = <(String, String, List<String>, String)>[
  ('Çevresi 20 cm olan daire dilimleri arasında alanı en büyük olanın merkez açısı kaç radyandır?', '2', ['1', 'π/2', 'π'], '2r + rθ = 20 iken alan = r(20 − 2r)/2 en büyük r = 5\'te olur; θ = (20 − 10)/5 = 2 radyan.'),
  ('Ekvator çevresini yaklaşık 40 000 km kabul eden bir ölçüme göre aynı meridyen üzerinde enlemleri 1° farklı iki noktanın arasındaki yay yaklaşık kaç km\'dir?', '111', ['40', '360', '1110'], '40 000 / 360 ≈ 111 km; bu, Dünya üzerinde 1°\'lik merkez açıya karşılık gelen yaydır.'),
  ('θ açısına π radyan eklendiğinde birim çemberdeki karşılık nokta, ilk noktaya göre nerede konumlanır?', 'Orijine göre simetriğindedir', ['x eksenine göre simetriğindedir', 'y eksenine göre simetriğindedir', 'İlk noktayla çakışır'], 'π eklemek noktayı yarım tur döndürür; (x, y) noktası (−x, −y) olur.'),
  ('sin x < 0 iken √(1 − cos²x) ifadesi aşağıdakilerden hangisine eşittir?', '−sin x', ['sin x', '|cos x|', 'cos x'], '√(sin²x) = |sin x| ve sin x < 0 olduğundan sonuç −sin x olur.'),
  ('Bir dik üçgende hipotenüse ait yükseklik, hipotenüsü 4 cm ve 9 cm\'lik parçalara ayırıyor. Küçük dar açının tanjantı kaçtır?', '2/3', ['4/9', '3/2', '2/√13'], 'Yükseklik h² = 4·9 ⇒ h = 6. Küçük açı 9 cm\'lik parçanın ucundaki açıdır; tan = 6/9 = 2/3.'),
  ('Dik üçgenin dar açılarından biri α\'dır. sin α = 2 cos α eşitliği sağlanıyorsa bu üçgenin kısa dik kenarının hipotenüse oranı kaçtır?', '1/√5', ['1/2', '2/√5', '1/(2√5)'], 'tan α = 2 ⇒ dik kenarlar 1 ve 2, hipotenüs √5; kısa kenar/hipotenüs = 1/√5.'),
  ('1°\'den 89°\'ye kadar ardışık tam sayı derecelerin sinüslerinin kareleri toplanırsa (sin²1° + … + sin²89°) hangi değer bulunur?', '44,5', ['44', '45', '89/2 + 1'], 'sin²k° + sin²(90 − k)° = sin²k° + cos²k° = 1; 44 çift 44 eder, sin²45° = 1/2 eklenince 44,5 olur.'),
  ('Küplerin toplamı özdeşliğinden yararlanarak sin⁶x + cos⁶x toplamını daha düşük kuvvetlerle yazınız.', '1 − 3sin²x·cos²x', ['1 − 2sin²x·cos²x', '1', '1 + 3sin²x·cos²x·(−2)'], 'a³ + b³ = (a + b)³ − 3ab(a + b) ile a = sin²x, b = cos²x alınırsa 1 − 3sin²x cos²x bulunur.'),
  ('cos(π − x) · tan(π + x) / sin(π/2 + x) ifadesi en sade biçimde nasıl yazılır?', '−tan x', ['tan x', '−cot x', '−sin x·tan x'], 'cos(π − x) = −cos x, tan(π + x) = tan x, sin(π/2 + x) = cos x; sonuç −cos x·tan x / cos x = −tan x.'),
  ('sin 100° + sin 200° + sin 300° + … + sin 3600° toplamı (açılar 100°\'er artıyor, 36 terim) kaçtır?', '0', ['1', '36', '−1'], 'Esas ölçüler 0°, 20°, 40°, …, 340° açılarının her birini ikişer kez verir. Eşit aralıklı bu açılarda θ ile θ + 180°\'nin sinüsleri birbirini götürdüğünden toplam sıfırdır.'),
  ('a = sin 1, b = sin 2, c = sin 3 (açılar radyan) sayılarının sıralaması nasıldır?', 'c < a < b', ['a < b < c', 'c < b < a', 'a < c < b'], 'sin 2 = sin(π − 2) = sin 1,14 ve sin 3 = sin(π − 3) = sin 0,14 olur; 0,14 < 1 < 1,14 ve sinüs dar açılarda artandır.'),
  ('x radyan cinsinden ve 0 < x < π/2 olmak üzere sin x, x ve tan x niceliklerinin sıralaması hangisidir?', 'sin x < x < tan x', ['x < sin x < tan x', 'sin x < tan x < x', 'tan x < x < sin x'], 'Birim çemberde sinüs dik kenarı, yay uzunluğu x ve tanjant doğru parçası karşılaştırıldığında bu sıralama geometrik olarak elde edilir.'),
  ('y = sin x eğrisinin simetri eksenlerinden biri aşağıdakilerden hangisidir?', 'x = π/2', ['x = π', 'x = 0', 'y = 1'], 'sin(π/2 + t) = sin(π/2 − t) = cos t olduğundan eğri x = π/2 doğrusuna göre simetriktir.'),
  ('Bir trigonometrik fonksiyonun en büyük değeri 7, en küçük değeri −1 ve periyodu π\'dir. Bu fonksiyon aşağıdakilerden hangisi olabilir?', 'y = 4 sin 2x + 3', ['y = 7 sin 2x − 1', 'y = 4 sin x + 3', 'y = 3 sin 2x + 4'], 'Genlik (7 − (−1))/2 = 4, orta değer (7 + (−1))/2 = 3, periyot π ⇒ katsayı 2.'),
  ('f(x) = sin³x · cos x + tan x fonksiyonu için hangisi doğrudur?', 'Tektir', ['Çifttir', 'Ne tek ne çifttir', 'Periyodu yoktur'], 'sin³(−x) = −sin³x, cos(−x) = cos x ve tan(−x) = −tan x; her terim tek olduğundan toplam tektir.'),
  ('Her x ∈ [−1, 1] için arcsin x + arccos x toplamı neye eşittir?', 'π/2', ['π', '0', '2π'], 'arcsin x = θ ise x = cos(π/2 − θ) ve π/2 − θ ∈ [0, π]; dolayısıyla arccos x = π/2 − θ.'),
  ('Üç kat açı açılımını kullanarak 4 sin³x − 3 sin x + sin 3x ifadesini sadeleştirdiğinizde geriye ne kalır?', '0', ['2 sin 3x', '−2 sin 3x', 'sin x'], 'sin 3x = 3 sin x − 4 sin³x olduğundan 4 sin³x − 3 sin x = −sin 3x; toplam sıfırdır.'),
  ('Son iki terimi çarpıma dönüştürerek sin 10° + sin 50° − sin 70° işlemini sonuçlandırınız.', '0', ['1/2', 'sin 10°', '√3/2'], 'sin 50° − sin 70° = 2 cos 60° sin(−10°) = −sin 10°; toplam sıfır.'),
  ('Ardışık iki katı açıların kosinüsleri olan cos 20°, cos 40° ve cos 80° sayılarının çarpımını bulunuz.', '1/8', ['1/4', '√3/8', '1/16'], 'Çarpım sin 20° ile çarpılıp bölünür; iki kat açı üç kez uygulanınca sin 160°/(8 sin 20°) = 1/8 bulunur.'),
  ('sin²x − 5 sin x + 6 = 0 denkleminin gerçek sayılarda kaç çözümü vardır?', 'Hiç çözümü yoktur', ['Sonsuz çözümü vardır', 'İki çözümü vardır', 'Bir çözümü vardır'], 'Kökler sin x = 2 ve sin x = 3 olup ikisi de [−1, 1] dışında kaldığından çözüm yoktur.'),
  ('y = sin x eğrisi ile y = x/10 doğrusu (x radyan) kaç noktada kesişir?', '7', ['3', '5', '9'], 'Doğru y = x/10 yalnız [−10, 10] aralığında sinüs eğrisini kesebilir; bu aralıkta pozitif tarafta 3, negatif tarafta 3 ve orijinde 1 olmak üzere 7 kesişim vardır.'),
  ('cos x = m denkleminin (0, π) aralığında tam bir çözümü olması için m hangi aralıkta olmalıdır?', '(−1, 1)', ['[−1, 1]', '(0, 1)', '[0, 1)'], 'Kosinüs (0, π) aralığında 1\'den −1\'e kesin azalandır ve uç değerleri almaz; her m ∈ (−1, 1) için tek çözüm vardır.'),
  ('A = 30°, a = 5 ve b = 8 verilen bir üçgen için B açısı hakkında hangisi doğrudur?', 'İki farklı üçgen oluşabilir', ['Hiç üçgen oluşmaz', 'Tek bir dik üçgen oluşur', 'Yalnız tek bir dar açılı üçgen oluşur'], 'sin B = 8·(1/2)/5 = 0,8 < 1 ve b > a olduğundan B ≈ 53,13° veya B ≈ 126,87° olabilir (belirsiz durum).'),
  ('Kenarları a, b, c olan bir üçgende a² + b² < c² eşitsizliği sağlanıyorsa C açısı için ne söylenir?', 'C geniş açıdır', ['C dar açıdır', 'C dik açıdır', 'C açısı 60°\'ye eşittir'], 'cos C = (a² + b² − c²)/(2ab) < 0 olduğundan C, 90° ile 180° arasındadır.'),
  ('İki kenarı sabit 5 ve 12 cm olan üçgenlerden alanı en büyük olanın alanı kaç cm²\'dir?', '30', ['60', '32,5', '15'], 'Alan (1/2)·5·12·sin θ ifadesi sin θ = 1 (θ = 90°) iken en büyüktür: 30 cm².'),
  ('Alan, kenarlar ve çevrel çember yarıçapı arasındaki Alan = abc/(4R) bağıntısı hangi iki formülün birleşiminden elde edilir?', '(1/2)ab·sin C ve c = 2R·sin C', ['Heron formülü ve Pisagor bağıntısı', 'Kosinüs teoremi ve iç teğet yarıçapı', 'Taban·yükseklik/2 ve tan C = c/2R'], 'sin C = c/(2R) alan formülünde yerine yazılırsa (1/2)ab·c/(2R) = abc/(4R) bulunur.'),
  ('20 m yüksekliğindeki bir binanın tepesinden karşıdaki bir kulenin tepesi 45°\'lik yükselme açısıyla, dibi 30°\'lik alçalma açısıyla görülüyor. Kulenin yüksekliği kaç metredir?', '20 + 20√3', ['40', '20√3', '20 + 20√3/3'], 'Yatay uzaklık d = 20/tan 30° = 20√3. Kulenin bina tepesinden yüksekte kalan kısmı d·tan 45° = 20√3; toplam 20 + 20√3 m.'),
  ('Bir gözlemci yükselme açısı α olan bir tepeye d metre yaklaşınca açı β\'ya çıkıyor. Tepenin yüksekliğini veren ifade hangisidir?', 'd/(cot α − cot β)', ['d/(tan β − tan α)', 'd·(cot α − cot β)', 'd·tan α·tan β'], 'h·cot α − h·cot β = d olduğundan h = d/(cot α − cot β).'),
  ('Bir yürüyüşçü önce doğuya 6 km, sonra kuzeyle 30° açı yapan kuzeydoğu doğrultusunda 4 km yürüyor. Başlangıca uzaklığı kaç km\'dir?', '2√19', ['10', '2√13', '√52 + 6'], 'İki yol arasındaki iç açı 90° + 30° = 120°\'dir. d² = 36 + 16 − 2·6·4·cos 120° = 52 + 24 = 76 ⇒ d = 2√19 km.'),
  ('Bir radarın 40 km kuzeyinde ve 30 km doğusunda bir uçak bulunuyor. Uçağın radardan görülme yönü kuzeyden doğuya doğru ölçülen θ açısı için tan θ kaçtır?', '3/4', ['4/3', '3/5', '4/5'], 'Kuzey bileşeni komşu, doğu bileşeni karşı kenar olarak alınır: tan θ = 30/40 = 3/4.'),
  ('(sin x + cos x)² + (sin x − cos x)² toplamı x\'ten bağımsız olarak hangi sayıya eşittir?', '2', ['1', '4', '0'], 'İki açılım toplanınca çapraz terimler (±2 sin x cos x) birbirini götürür: 2(sin²x + cos²x) = 2.'),
  ('Açıları her adımda ikiye katlanan cos(π/7), cos(2π/7), cos(4π/7) kosinüslerinin çarpımı hangi sayıya eşittir?', '−1/8', ['1/8', '−1/4', '−1/16'], 'Çarpım sin(π/7) ile genişletilip iki kat açı üç kez uygulanırsa sin(8π/7)/(8 sin(π/7)) = −1/8 bulunur.'),
  ('Düzgün beşgenle ilişkili sin(π/5), sin(2π/5), sin(3π/5), sin(4π/5) değerlerinin hepsi birlikte çarpılırsa sonuç ne olur?', '5/16', ['1/16', '5/8', '√5/16'], 'sin(3π/5) = sin(2π/5), sin(4π/5) = sin(π/5) olduğundan çarpım (sin 36°·sin 72°)² = (√5/4)² = 5/16.'),
  ('(1 + tan 1°)(1 + tan 44°) çarpımının değeri kaçtır?', '2', ['1', 'tan 45°', '√2'], 'a + b = 45° ise tan(a + b) = 1\'den tan a + tan b = 1 − tan a tan b çıkar; çarpım 1 + (tan a + tan b) + tan a tan b = 2.'),
  ('Dik açısı bulunmayan her ABC üçgeninde tan A + tan B + tan C toplamı hangi ifadeye eşittir?', 'tan A·tan B·tan C', ['1', '0', 'tan A·tan B + tan C'], 'tan(A + B) = −tan C açılımı düzenlenirse tan A + tan B + tan C = tan A tan B tan C elde edilir.'),
  ('ABC üçgeninde sin A = 2 sin B·cos C bağıntısı sağlanıyorsa üçgen hangi türdendir?', 'İkizkenar (b = c)', ['Eşkenar', 'Dik (A = 90°)', 'Çeşitkenar ve geniş açılı'], 'sin A = sin(B + C) = sin B cos C + cos B sin C; eşitlikten sin(B − C) = 0 ⇒ B = C.'),
  ('Bir üçgende a = 7, b = 8, c = 5 ise cos A + cos B + cos C toplamı kaçtır?', '10/7', ['3/2', '1', '19/14'], 'cos A = (64 + 25 − 49)/80 = 1/2, cos B = (49 + 25 − 64)/70 = 1/7, cos C = (49 + 64 − 25)/112 = 11/14; toplam 20/14 = 10/7.'),
  ('Her üçgende A/2 + B/2 + C/2 = 90° olduğundan tan(A/2)·tan(B/2) + tan(B/2)·tan(C/2) + tan(C/2)·tan(A/2) toplamı neye eşittir?', '1', ['0', '3', '√3'], 'x + y + z = 90° iken tan x tan y + tan y tan z + tan z tan x = 1 özdeşliği geçerlidir.'),
  ('sin x > cos x eşitsizliği [0, 2π) aralığında hangi aralıkta sağlanır?', '(π/4, 5π/4)', ['(0, π/4)', '(π/4, 3π/4)', '(5π/4, 2π)'], 'sin x − cos x = √2 sin(x − π/4) > 0 ⇒ 0 < x − π/4 < π ⇒ π/4 < x < 5π/4.'),
  ('x = 0,1 radyan için sin x yerine x kullanılırsa yapılan bağıl hata yaklaşık yüzde kaçtır? (sin 0,1 ≈ 0,09983)', '%0,17', ['%1,7', '%10', '%0,017'], 'Hata (0,1 − 0,09983)/0,09983 ≈ 0,0017, yani yaklaşık %0,17\'dir; açı küçüldükçe hata hızla azalır.'),
  ('Küçük açı yaklaşımı sin x ≈ x, x yerine derece cinsinden değer yazılırsa neden yanlış sonuç verir?', 'Yaklaşım radyan ölçüsüne dayanır', ['Derece her zaman radyandan küçüktür', 'Sinüs derece cinsinden tanımsızdır', 'Derece cinsinden açılar negatif olamaz'], 'sin x ≈ x bağıntısı yay uzunluğu ile yarıçap oranına (radyana) dayanır; örneğin sin 1° ≈ 0,01745 olup 1\'e yakın değildir.'),
  ('Ay\'ın Dünya\'dan görünen açısal çapı yaklaşık 0,5°\'dir. Ay\'ın uzaklığı yaklaşık 384 000 km ise küçük açı yaklaşımıyla çapı yaklaşık kaç km bulunur?', '3350', ['1920', '6700', '33 500'], '0,5° ≈ 0,00873 radyan; çap ≈ 384 000·0,00873 ≈ 3350 km (gerçek değer yaklaşık 3475 km\'dir).'),
  ('Bir limanda su derinliği d(t) = 5 + 2 sin(πt/6) metre ile modelleniyor (t saat). Derinliğin 6 m\'den fazla olduğu süre bir periyot içinde kaç saattir?', '4', ['6', '3', '8'], 'sin(πt/6) > 1/2 ⇒ π/6 < πt/6 < 5π/6 ⇒ 1 < t < 5; 12 saatlik periyotta 4 saat sürer.'),
  ('Kutupsal koordinatları (3, 20°) ve (5, 80°) olan iki nokta arasındaki uzaklık kaç birimdir?', '√19', ['2', '√34', '√(34 − 15√3)'], 'Noktaların orijinle oluşturduğu üçgende aradaki açı 60°\'dir; d² = 9 + 25 − 2·3·5·(1/2) = 19.'),
  ('Kutupsal denklemi r = 2 cos θ olan eğrinin kartezyen denklemi hangisidir?', 'x² + y² = 2x', ['x² + y² = 2y', 'x² + y² = 4', 'x² + y² = 2x + 2y'], 'Her iki yan r ile çarpılırsa r² = 2r cos θ ⇒ x² + y² = 2x; merkezi (1, 0), yarıçapı 1 olan çemberdir.'),
  ('Trigonometriyi gökbilimden bağımsız bir matematik dalı olarak ele alan "Şeklü\'l-Kattâ" adlı eserin yazarı olan 13. yüzyıl bilgini kimdir?', 'Nasîrüddin Tûsî', ['Muhammed bin Musa Harezmî', 'Ömer Hayyam', 'İbn Sina'], 'Merağa Rasathanesi\'nin kurucusu Nasîrüddin Tûsî bu eserinde düzlem ve küresel trigonometriyi sistemli olarak işlemiştir.'),
  ('Bîrûnî, Dünya\'nın yarıçapını hesaplarken hangi trigonometrik yöntemi kullanmıştır?', 'Dağdan ufka bakışın alçalma açısını ölçmek', ['Gölge uzunluklarını iki kentte karşılaştırmak', 'Ay tutulmasında gölgenin eğriliğini ölçmek', 'Yıldızların doğuş saatlerini kaydetmek'], 'Bîrûnî, yüksekliği bilinen bir dağdan ufuk çizgisine olan alçalma açısını ölçmüş ve dik üçgenden yarıçapı hesaplamıştır.'),
  ('Kosinüs teoreminin geometrik bir biçimi Öklid\'in Elementler adlı eserinde hangi şekilde yer alır?', 'Pisagor bağıntısının geniş ve dar açılı üçgenlere genellemesi', ['Çemberin çevresi ile çapı arasındaki oranın hesaplanması olarak', 'Paralel aksiyomunun sonucu olarak', 'Asal sayıların sonsuzluğunun kanıtında'], 'Elementler\'in II. kitabında geniş ve dar açılı üçgenler için kare alanlarına dayanan eşdeğer önermeler bulunur; trigonometrik dil kullanılmaz.'),
  ('Küresel üçgenleri inceleyen "Sphaerica" adlı eseriyle küresel trigonometrinin öncülerinden sayılan İskenderiyeli matematikçi kimdir?', 'Menelaos', ['Heron', 'Diofantos', 'Papus'], 'MS 1. yüzyılda yaşayan İskenderiyeli Menelaos, Sphaerica\'da küre yüzeyindeki üçgenleri incelemiş; Menelaos teoremi de onun adını taşır.'),
  ('Bir dikdörtgenin kenarları 5 ve 12 cm\'dir. Köşegenlerin kesiştiği noktada oluşan dar açının kosinüsü kaçtır?', '119/169', ['5/13', '120/169', '25/169'], 'Köşegen yarıları 6,5 cm\'dir. Kosinüs teoremiyle 5 cm\'lik kenarın karşısındaki açı için cos θ = (6,5² + 6,5² − 25)/(2·6,5²) = 119/169.'),
  ('Dik üçgende bir dar açı için sin α + cos α değeri hangi aralıkta bulunur?', '(1, √2]', ['(0, 1)', '[1, 2]', '(√2, 2)'], 'sin α + cos α = √2·sin(α + 45°); dar açıda α + 45° ∈ (45°, 135°) olduğundan değer 1\'den büyük, en çok √2\'dir.'),
  ('Birim çember üzerinde birinci bölgedeki P noktası için orijinden P\'ye çizilen yarıçapın x ekseniyle yaptığı açı 40°\'dir. P\'nin y = x doğrusuna göre simetriği olan noktanın koordinatları hangisidir?', '(sin 40°, cos 40°)', ['(cos 40°, sin 40°)', '(−sin 40°, cos 40°)', '(cos 50°, −sin 50°)'], 'y = x\'e göre simetride koordinatlar yer değiştirir: (cos 40°, sin 40°) → (sin 40°, cos 40°); bu 50°\'lik açıya karşılık gelir.'),
  ('Birim çemberde θ açısına karşılık gelen nokta ile (1, 0) noktası arasındaki kirişin uzunluğu hangi ifadeye eşittir?', '2 sin(θ/2)', ['2 sin θ', 'sin(θ/2)', '2 cos(θ/2)'], 'Merkez açısı θ olan bir kiriş yarıçap 1 için 2·sin(θ/2) uzunluğundadır (ikizkenar üçgeni ikiye bölerek).'),
  ('x dar açı olmak üzere sin(π − x), cos(π + x) ve tan(2π − x) değerleri çarpılırsa sonuç hangi işarettedir?', 'Pozitif', ['Negatif', 'Sıfır', 'x\'e bağlıdır'], 'sin(π − x) = sin x > 0, cos(π + x) = −cos x < 0, tan(2π − x) = −tan x < 0; iki negatifin çarpımı pozitiftir.'),
  ('Bir futbol sahasında kale direkleri arası 7,32 m\'dir. Bir oyuncu bir direğe 12 m, diğerine 15 m uzaklıkta duruyorsa şut açısının kosinüsü hangi ifadeyle bulunur?', '(144 + 225 − 7,32²)/(2·12·15)', ['(144 + 225 + 7,32²)/(2·12·15)', '(7,32² − 144 − 225)/(12·15)', '(144 + 225 − 7,32²)/(12·15·4)'], 'Kosinüs teoremi: 7,32² = 12² + 15² − 2·12·15·cos θ; buradan cos θ çekilir.'),
  ('Bir üçgende a² = b² + c² + bc bağıntısı sağlanıyorsa A açısı kaç derecedir?', '120°', ['60°', '90°', '150°'], 'Kosinüs teoremiyle karşılaştırılırsa −2bc·cos A = bc ⇒ cos A = −1/2 ⇒ A = 120°.'),
  ('y = sin x ve y = cos x eğrileri [0, 2π] aralığında kesiştiklerinde ortak ordinat değerleri hangileridir?', '√2/2 ve −√2/2', ['1 ve −1', '1/2 ve −1/2', '√3/2 ve −√3/2'], 'Kesişim π/4 ve 5π/4\'tedir; bu noktalarda ordinat sırasıyla √2/2 ve −√2/2 olur.'),
  ('Tanjantın sinüse eşit olduğu açılar, yani tan x = sin x eşitliğini sağlayan ve 0 ile 2π arasında (0 dahil) kalan değerler hangileridir?', '0 ve π', ['0 ve π/2', 'π/4 ve 5π/4', '0, π/2 ve π'], 'sin x/cos x − sin x = sin x(1 − cos x)/cos x = 0 ⇒ sin x = 0 veya cos x = 1; aralıkta 0 ve π bulunur.'),
  ('Bir kalemin gölge uzunluğu L = 3 sin θ + 4 cos θ biçiminde değişiyor. L\'nin alabileceği en büyük değer hangi tan θ değerinde gerçekleşir?', '3/4', ['4/3', '1', '3/5'], 'En büyük değer (sin θ, cos θ) vektörü (3, 4) ile aynı yönde olduğunda alınır: sin θ = 3/5, cos θ = 4/5 ⇒ tan θ = 3/4.'),
  ('cos 2x\'i sin x cinsinden yazarak y = cos 2x + 2 sin x ifadesinin ulaşabildiği en yüksek değeri belirleyiniz.', '3/2', ['3', '1', '2 + √2'], 'cos 2x = 1 − 2sin²x ⇒ y = −2t² + 2t + 1 (t = sin x); tepe t = 1/2\'de, değer −1/2 + 1 + 1 = 3/2.'),
  ('sec²x + csc²x toplamının alabileceği en küçük değer kaçtır?', '4', ['2', '1', '2√2'], 'sec²x + csc²x = 1/(sin²x cos²x) = 4/sin²2x; sin²2x en çok 1 olduğundan en küçük değer 4\'tür.'),
  ('Bir üçgenin iki kenarı aynı kalırken aralarındaki açı 30°\'den 150°\'ye çıkarılırsa alanı nasıl değişir?', 'Değişmez', ['İki katına çıkar', 'Yarıya iner', 'Beş katına çıkar'], 'sin 30° = sin 150° = 1/2 olduğundan alan formülündeki değer aynı kalır.'),
  ('Bir balonun hemen altındaki noktadan 100 m uzaklaşan bir gözlemci balonu 60°\'lik yükselme açısıyla görüyor. 200 m daha uzaklaşınca açı kaç derece olur? (Balon sabit yükseklikte)', '30°', ['45°', '15°', '22,5°'], 'Yükseklik 100√3 m. Yeni uzaklık 300 m: tan θ = 100√3/300 = √3/3 ⇒ θ = 30°.'),
  ('Bir binanın gölgesi, Güneş\'in yükselme açısı 60° iken 15 m, 30° iken kaç metredir?', '45', ['30', '15√3', '60'], 'Yükseklik h = 15√3 m; 30°\'de gölge h/tan 30° = 15√3·√3 = 45 m.'),
  ('İki gözlem noktası arasındaki uzaklık 1 km\'dir. Bir uçak bu iki noktanın tam ortasının üstünde uçarken her iki noktadan 60°\'lik yükselme açısıyla görülüyor. Uçağın yüksekliği kaç metredir?', '500√3', ['1000√3', '500', '250√3'], 'Her noktadan uçağın izdüşümüne uzaklık 500 m\'dir; h = 500·tan 60° = 500√3 m.'),
  ('Bir sahil güvenlik botu A noktasından kuzeye 8 km, sonra batıya 6 km gidiyor. Başlangıç noktasına dönmek için hangi yöne ve ne kadar gitmesi gerekir?', 'Güneydoğuya, 10 km', ['Kuzeydoğuya doğru 10 km', 'Güneybatıya doğru 14 km', 'Güneydoğuya doğru 14 km'], 'Bot A\'nın 8 km kuzeyinde ve 6 km batısındadır; dönüş doğrultusu güney ve doğu bileşenli, uzunluğu √(64 + 36) = 10 km.'),
  ('"(sin x)⁻¹" ile "sin⁻¹x" gösterimleri hakkında hangisi doğrudur?', 'İlki csc x, ikincisi arcsin x anlamındadır', ['İkisi de aynı biçimde 1/sin x anlamındadır', 'İkisi de arcsin x anlamındadır', 'İlki arcsin x, ikincisi 1/sin x anlamındadır'], 'sin⁻¹x gösterimi ters fonksiyonu (arcsin) belirtir; çarpmaya göre ters ise (sin x)⁻¹ = csc x biçiminde yazılır.'),
  ('Bir öğrenci sin²x = sin x denkleminde iki yanı sin x\'e bölüp yalnız sin x = 1 sonucunu buluyor. Bu çözümdeki hata nedir?', 'sin x = 0 çözümlerini kaybetmiştir', ['sin x = −1 çözümlerini eklemiştir', 'Hiçbir hata yoktur', 'Fazladan cos x = 0 kökleri eklemiştir'], 'Sıfır olabilecek bir ifadeye bölmek kök kaybettirir; doğru yol sin x(sin x − 1) = 0 biçiminde çarpanlara ayırmaktır.'),
  ('tan(x + y) = (tan x + tan y)/(1 − tan x·tan y) formülü hangi durumda kullanılamaz?', 'tan x·tan y = 1 iken', ['x = y olduğunda', 'x + y = 0 olduğunda', 'tan x = 0 olduğunda'], 'Payda sıfır olur; bu durumda x + y = 90° + k·180° olup tan(x + y) tanımsızdır.'),
  ('Aşağıdakilerden hangisi her x gerçek sayısı için doğrudur?', 'cos(sin x) > 0', ['sin(cos x) > 0', 'sin x·cos x > 0', 'tan x > sin x'], 'sin x ∈ [−1, 1] ⊂ (−π/2, π/2) olduğundan kosinüsü her zaman pozitiftir. sin(cos x) ise cos x < 0 olduğunda negatiftir.'),
  ('Bir öğrenci cos(x/2) = ±√((1 + cos x)/2) formülünde işareti her zaman + alıyor. Hangi durumda yanlış sonuç bulur?', 'x/2 II. ya da III. bölgedeyken', ['x/2 birinci bölgede olduğunda', 'x/2 = 0 olduğunda', 'x açısı bir dar açı olduğunda'], 'Kosinüs II. ve III. bölgelerde negatiftir; işaret x/2\'nin bulunduğu bölgeye göre seçilmelidir.'),
  ('Sinüs teoremiyle bir açı bulunurken sin B = 0,6 elde edilirse neden dikkatli olunmalıdır?', 'B dar ya da geniş olabilir', ['B kesinlikle 36,87°\'dir', 'Sinüs teoremi geniş açılarda geçersizdir', 'sin B = 0,6 olan üçgen yoktur'], 'sin B = sin(180° − B) olduğundan B ≈ 36,87° veya ≈ 143,13° olabilir; açılar toplamı ve kenar ilişkileri kontrol edilir.'),
  ('Üç kenarı verilen bir üçgende kosinüs teoremi ile en büyük açıyı bulmanın, sinüs teoremi kullanmaktan daha güvenli olmasının nedeni nedir?', 'Kosinüs açıyı tek türlü belirler', ['Kosinüs teoremi daha kısa olduğu için', 'Sinüs teoremi kenarlarla çalışmadığı için', 'Kosinüs her zaman pozitif olduğu için'], '(0°, 180°) aralığında kosinüs bire birdir; sinüs ise dar ve geniş açılar için aynı değeri verebilir.'),
  ('Eğim açısı α olan sürtünmesiz bir rampada m kütleli cismin ağırlığının rampaya paralel bileşeni hangi ifadedir?', 'm·g·sin α', ['m·g·cos α', 'm·g·tan α', 'm·g/sin α'], 'Ağırlık vektörü rampaya paralel ve dik iki bileşene ayrılır; paralel bileşen mg sin α, dik bileşen mg cos α olur.'),
  ('Eşit kenarları 1 birim ve tepe açısı 2α olan ikizkenar üçgenin alanının iki yoldan hesaplanması hangi formülü kanıtlar?', 'sin 2α = 2 sin α cos α', ['cos 2α = 1 − 2sin²α', 'tan 2α = 2tan α/(1 − tan²α)', 'sin²α + cos²α = 1'], 'Alan (1/2)·1·1·sin 2α ile (1/2)·taban·yükseklik = (1/2)(2 sin α)(cos α) eşitlenince sin 2α = 2 sin α cos α çıkar.'),
  ('Bir müzik sentezleyicide iki ses dalgası 2 sin(x/3) ve 5 cos(x/2) üst üste bindiriliyor. Oluşan toplam dalga hangi en küçük aralıkla kendini tekrar eder?', '12π', ['6π', '4π', '24π'], 'Periyotlar 6π ve 4π\'dir; bunların en küçük ortak katı 12π\'dir.'),
  ('π/5 ile aynı sinüs değerine sahip olan ve 0 ile π arasında kalan bütün açılar hangileridir?', 'π/5 ve 4π/5', ['π/5 ve 6π/5', 'yalnız π/5', 'π/5 ve 9π/5'], 'Sinüsü eşit açılar x = π/5 veya x = π − π/5 = 4π/5\'tir; ikisi de aralıktadır.'),
  ('Kosinüsü 0,99 olan açıların −π ile π arasında kaç tane olduğunu kosinüsün çift fonksiyon olmasından yararlanarak belirleyiniz.', '2', ['1', '0', '4'], 'Kosinüs çift ve [0, π]\'de azalan olduğundan bir pozitif ve bir negatif çözüm vardır.'),
  ('t = sin x + cos x dönüşümü yapılarak sin x + cos x + sin x·cos x toplamının ulaşabildiği en büyük değer bulunursa sonuç nedir?', '√2 + 1/2', ['2', '1 + √2', '3/2'], 't = sin x + cos x ∈ [−√2, √2] için y = t + (t² − 1)/2; artan olduğu bölgede t = √2 ⇒ √2 + 1/2.'),
  ('ABC üçgeninde sin²A + sin²B = sin²C bağıntısı sağlanıyorsa C açısı kaç derecedir?', '90°', ['60°', '120°', '45°'], 'Sinüs teoremiyle sinüsler kenarlarla orantılı olduğundan a² + b² = c² olur; Pisagor bağıntısının tersi gereği C = 90°.'),
  ('y = a·sin(bx) eğrisi (a, b > 0) (π/4, 3) noktasından geçiyor ve bu nokta eğrinin ilk tepe noktasıdır. a + b toplamı kaçtır?', '5', ['4', '6', '3 + π/4'], 'Tepe değeri a = 3. İlk tepe bx = π/2\'de olduğundan b·π/4 = π/2 ⇒ b = 2; toplam 5.'),
  ('y = sin x ve y = sin(π − x) eğrileri için hangisi doğrudur?', 'Aynı eğridir', ['x eksenine göre simetriktir', 'Orijine göre simetriktir', 'π birim ötelenmiştir'], 'sin(π − x) = sin x özdeşliği her x için sağlandığından iki eğri çakışır.'),
  ('Bir üçgende a = 6, b = 10 ve A = 45° verilmiştir. Bu verilere uygun kaç üçgen çizilebilir?', 'Hiç', ['1', '2', 'Sonsuz'], 'sin B = 10·(√2/2)/6 ≈ 1,18 > 1 olduğundan böyle bir B açısı yoktur.'),
  ('cos x > sin x eşitsizliğini sağlayan dar açılar hangi aralıktadır?', '(0°, 45°)', ['(45°, 90°)', '(0°, 90°)', '(30°, 60°)'], 'Dar açılarda kosinüs azalan, sinüs artandır ve 45°\'de eşitlenir; öncesinde kosinüs büyüktür.'),
  ('Gelgit modeli h(t) = 3 + 1,5 cos(πt/6) metre ile veriliyor (t saat). Ardışık iki yüksek su arasında kaç saat vardır?', '12', ['6', '24', '4,5'], 'Periyot 2π/(π/6) = 12 saattir; yüksek sular bu aralıkla tekrarlanır.'),
  ('cos 3x = 0 iken x = 30° alınarak cos 3x formülünden hangi değer doğrulanır?', 'cos²30° = 3/4', ['sin²30° = 3/4', 'cos 30° = 1/2', 'cos²30° = 1/3 ve sin²30° = 2/3'], '4cos³x − 3cos x = cos x(4cos²x − 3) = 0 ⇒ cos²30° = 3/4; bu bilinen değerle uyumludur.'),
  ('Bir kuleden aynı doğrultudaki iki aracın alçalma açıları 45° ve 30° ölçülüyor; kule 50 m yüksekliktedir. Araçlar arasındaki uzaklık kaç metredir?', '50√3 − 50', ['50√3', '50 − 50√3/3', '100'], 'Yatay uzaklıklar 50/tan 45° = 50 ve 50/tan 30° = 50√3; fark 50√3 − 50 m.'),
  ('Bir ABC üçgeninde |AB| = |AC| = 10 cm\'dir. A açısı ne olursa olsun alanın alabileceği en büyük değer kaç cm²\'dir?', '50', ['100', '25√3', '25'], 'Alan (1/2)·10·10·sin A = 50 sin A en çok 50 cm²\'dir (A = 90°).'),
  ('a·sin x = 3 denkleminin gerçek çözümü olmaması için a hangi aralıkta olmalıdır?', '(−3, 3)', ['[−3, 3]', '(3, ∞)', '(0, 3) ∪'], 'sin x = 3/a olmalıdır; çözüm için |3/a| ≤ 1 yani |a| ≥ 3 gerekir. Çözümsüzlük |a| < 3 (a = 0 dahil) durumudur.'),
  ('cos x·cos(60° − x)·cos(60° + x) özdeşliğinden yararlanarak 10°, 50° ve 70° açılarının kosinüslerinin çarpımını hesaplayınız.', '√3/8', ['1/8', '√3/4', '√3/16 + 1'], 'cos x·cos(60° − x)·cos(60° + x) = (cos 3x)/4 özdeşliğinde x = 10° alınırsa cos 30°/4 = √3/8 bulunur.'),
  ('Kuvvet indirme formülü kullanılarak 10°, 50° ve 70° açılarının sinüs karelerinin toplamı bulunursa sonuç nedir?', '3/2', ['1', '3/4', '3/2 − √3/4'], 'sin²θ = (1 − cos 2θ)/2 yazılırsa toplam 3/2 − (cos 20° + cos 100° + cos 140°)/2 olur; parantez sıfırdır.'),
  ('Kutupsal koordinatlarda r = 1/sin θ denklemi kartezyen koordinatlarda hangi eğriyi verir?', 'y = 1 doğrusu', ['x = 1 doğrusu', 'Merkezi orijinde olan birim çember', 'y = x doğrusu'], 'r·sin θ = 1 ⇒ y = 1 elde edilir; bu yatay bir doğrudur.'),
  ('Küçük açı yaklaşımı tan x ≈ x kullanılırsa tan 0,05 (radyan) için hangi değer bulunur ve gerçek değer bundan büyük mü küçük mü?', '0,05; gerçek değer biraz büyük', ['0,05; gerçek değer biraz daha küçüktür', '0,5; gerçek değer eşittir', '0,0025; gerçek değer büyüktür'], 'Dar açılarda tan x > x olduğundan yaklaşım gerçek değeri biraz eksik verir (tan 0,05 ≈ 0,05004).'),
  ('R = v²·sin 2θ / g menzil bağıntısına göre aynı hızla 30° ve 60° açılarla atılan iki cismin menzilleri arasındaki ilişki nedir?', 'Eşittir', ['60°\'lik atışınki iki katıdır', '30°\'lik atışınki iki katıdır', '60°\'lik atışınki √3 katıdır'], 'sin 60° = sin 120° olduğundan iki atışta sin 2θ aynıdır; tümler açılarla yapılan atışların menzilleri eşittir.'),
  ('Fransız matematikçi Joseph Fourier\'nin adıyla anılan yöntemde periyodik bir fonksiyon hangi biçimde ifade edilir?', 'Sinüs ve kosinüs dalgalarının toplamı', ['Logaritmik terimlerin sonsuz çarpımı olarak', 'Polinomların bölümü olarak', 'Üstel terimlerin farkı olarak'], 'Fourier serileri, periyodik sinyalleri farklı frekanslardaki sinüs ve kosinüs dalgalarının toplamı olarak yazar.'),
  ('(1, 1) noktası orijin etrafında pozitif yönde 45° döndürülünce hangi noktaya ulaşır?', '(0, √2)', ['(√2, 0)', '(1, √2)', '(√2/2, √2)'], 'Nokta orijine √2 uzaklıkta ve 45° doğrultusundadır; 45° daha dönünce 90° doğrultusuna, (0, √2) noktasına gelir.'),
  ('Taban kenarı 6 cm, yüksekliği 4 cm olan kare dik piramitte bir yan yüzün taban düzlemiyle yaptığı açının tanjantı kaçtır?', '4/3', ['2/3', '3/4', '√13/3'], 'Tepeden taban kenarının orta noktasına inen dik üçgende yükseklik 4, taban merkezinden kenara uzaklık 3\'tür: tan = 4/3.'),
  ('ABC ve ADE üçgenlerinde A açısı ortaktır; |AB| = 6, |AC| = 8, |AD| = 3 ve |AE| = 4\'tür (D, AB üzerinde; E, AC üzerinde). ADE\'nin alanı ABC\'nin alanının kaçta kaçıdır?', '1/4', ['1/2', '1/3', '1/16'], 'Alanlar (1/2)·kenar·kenar·sin A olduğundan oran (3·4)/(6·8) = 12/48 = 1/4\'tür; sin A sadeleşir.'),
  ('Bir üçgende sin A = sin B ise A ve B açıları için ne söylenebilir?', 'A = B\'dir', ['A + B = 180°\'dir', 'A + B = 90°\'dir', 'A = 2B\'dir'], 'sin A = sin B ⇒ A = B ya da A + B = 180°; üçgende ikinci durum olanaksız olduğundan A = B.'),
  ('ABC üçgeninde a·cos A = b·cos B ise üçgen için hangisi kesinlikle doğrudur?', 'İkizkenar ya da dik', ['Kesinlikle eşkenardır', 'Kesinlikle geniş açılıdır', 'Kesinlikle çeşitkenardır'], 'Sinüs teoremiyle sin A cos A = sin B cos B ⇒ sin 2A = sin 2B ⇒ A = B veya A + B = 90°.'),
  ('Bir dik üçgende dar açılar A ve B ise sin 2A ile sin 2B arasındaki ilişki nedir?', 'Eşittir', ['sin 2A = −sin 2B', 'sin 2A = cos 2B', 'Toplamları 1\'dir'], '2A + 2B = 180° olduğundan sin 2A = sin(180° − 2B) = sin 2B.'),
  ('Sinüsün içine x\'in karesi yazılarak oluşturulan sin(x²) için simetri ve periyot açısından doğru olan yargı hangisidir?', 'Çift fonksiyondur', ['Tek fonksiyondur', 'Periyodu 2π\'dir', 'Periyodu √(2π)\'dir'], 'f(−x) = sin((−x)²) = sin(x²) = f(x); ayrıca sıfırlar arası uzaklık giderek küçüldüğünden periyodik değildir.'),
  ('Mutlak değerin sinüsü olan sin|x| grafiği tekrarlama özelliği bakımından nasıl nitelendirilir?', 'Periyodik değildir', ['Esas periyodu π\'dir', 'Periyodu 2π\'dir', 'Tek fonksiyondur'], 'x ≥ 0 için sin x, x < 0 için −sin x gibi davranır; orijin çevresindeki bu kırılma başka yerde tekrarlanmadığından fonksiyon periyodik değildir.'),
  ('f(x) = tan x + cot x fonksiyonunun esas periyodu kaçtır?', 'π', ['π/2', '2π', 'π/4'], 'tan x + cot x = 2/sin 2x\'tir. x yerine x + π/2 yazılınca işaret değiştiğinden π/2 periyot olamaz; en küçük periyot π\'dir.'),
  ('f(x) = sin x + sin(√2·x) fonksiyonu periyodik midir?', 'Hayır, periyodik değildir', ['Evet; periyodu 2π\'dir', 'Evet; periyodu 2√2π\'dir', 'Evet; periyodu √2π\'dir'], 'Periyotlar 2π ve 2π/√2\'dir; oranları √2 irrasyonel olduğundan ortak bir kat yoktur.'),
  ('sin 1 (radyan) ile sin 1° değerleri karşılaştırılırsa hangisi doğrudur?', 'sin 1 daha büyüktür', ['sin 1° daha büyüktür', 'İkisi eşittir', 'İkisi de negatiftir'], '1 radyan ≈ 57,3° olduğundan sin 1 ≈ 0,84, sin 1° ≈ 0,017\'dir.'),
  ('tan 1 (1 radyan) değeri için hangisi doğrudur?', '1\'den büyüktür', ['1\'den küçüktür', '1\'e eşittir', 'Sıfır ile −1 arasındadır'], '1 radyan, π/4 ≈ 0,785 radyandan büyük ve π/2\'den küçük olduğundan tanjantı 1\'den büyüktür (≈ 1,557).'),
  ('5x = 90° eşitliğinden yola çıkılarak (2x = 90° − 3x) elde edilen sin 18° değeri hangisidir?', '(√5 − 1)/4', ['(√5 + 1)/4', '(√3 − 1)/2', '(√5 − 1)/2'], 'sin 2x = cos 3x eşitliği sin x cinsinden 4sin²x + 2 sin x − 1 = 0 verir; pozitif kök (√5 − 1)/4\'tür.'),
  ('sin x ≥ −√3/2 eşitsizliği [0, 2π) aralığında hangi kümede sağlanmaz?', '(4π/3, 5π/3)', ['(7π/6, 11π/6)', '(π, 2π)', '[4π/3, 5π/3]'], 'sin x < −√3/2 yalnız 4π/3 ile 5π/3 arasında gerçekleşir; uç noktalarda eşitlik olduğundan bu noktalar çözüme dahildir.'),
  ('Payda 7 olan açılar için cos(2π/7) + cos(4π/7) + cos(6π/7) ifadesinin tam değeri nedir?', '−1/2', ['1/2', '0', '−1'], 'Toplam S olsun; 2 sin(π/7)·S terimleri teleskopik olarak sin π − sin(π/7) = −sin(π/7) verir. Buradan S = −1/2 bulunur.'),
];
